settings.custom_liquid:
{%- if request.locale.iso_code == 'fr' -%}
  {%- assign nur_rating_text = '4,6/5 avis de testeurs' -%}
  {%- assign nur_rating_label = 'Noté 4,6 sur 5 par nos testeurs' -%}
{%- else -%}
  {%- assign nur_rating_text = '4.6/5 tester reviews' -%}
  {%- assign nur_rating_label = 'Rated 4.6 out of 5 by our testers' -%}
{%- endif -%}
<a class="nur-rating" href="{% if routes.root_url == '/' %}/pages/reviews{% else %}{{ routes.root_url }}/pages/reviews{% endif %}" aria-label="{{ nur_rating_label }}">
  <span class="nur-rating__stars" aria-hidden="true"><span class="nur-rating__fill">★★★★★</span>★★★★★</span>
  <span class="nur-rating__text">{{ nur_rating_text }}</span>
</a>
<style>
  .nur-rating { display: inline-flex; align-items: center; gap: 8px; text-decoration: none; color: #1A1A1A; font-size: 13px; }
  .nur-rating__stars { position: relative; display: inline-block; color: #E5DCC7; letter-spacing: 2px; font-size: 15px; line-height: 1; }
  .nur-rating__fill { position: absolute; inset: 0 auto 0 0; width: 92%; overflow: hidden; white-space: nowrap; color: #C8A96E; }
  .nur-rating__text { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: rgba(26,26,26,0.25); }
  .nur-rating:hover .nur-rating__text { text-decoration-color: #1A1A1A; }
</style>

{%- assign nur_title = closest.product.title | default: product.title -%}
{%- assign nur_title_parts = nur_title | split: ' - ' -%}
<style>
  .nur-pdp-title { margin: 0; }
  .nur-pdp-subtitle { margin: 6px 0 0; font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 15px; font-weight: 400; letter-spacing: 0.3px; line-height: 1.4; color: #4A4A4A; }
</style>
<h1 class="h3 nur-pdp-title">{{ nur_title_parts[0] }}</h1>
{%- if nur_title_parts.size > 1 -%}
  <p class="nur-pdp-subtitle">{{ nur_title_parts[1] }}</p>
{%- endif -%}

{%- liquid
  assign nur_fr = false
  if request.locale.iso_code == 'fr'
    assign nur_fr = true
  endif
  assign nur_root = routes.root_url
  if nur_root == '/'
    assign nur_root = ''
  endif
  # Early Access window (same deadline as the Early Access block): 25 Nov 2026 23:59 Paris
  assign nur_now = 'now' | date: '%s' | plus: 0
  assign nur_early = false
  if nur_now < 1795647540
    assign nur_early = true
  endif
  assign nur_product = closest.product | default: product
  assign nur_price = nur_product.selected_or_first_available_variant.price
  assign nur_deposit = nur_price | times: 20 | divided_by: 100
  assign nur_balance = nur_price | minus: nur_deposit
  assign nur_total_code = nur_price | times: 90 | divided_by: 100
  assign nur_balance_code = nur_total_code | minus: nur_deposit
-%}
<style>
  .nur-info { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; margin: 8px 0 4px; border-top: 1px solid #ECEAE5; }
  .nur-info__row { display: flex; width: 100%; align-items: center; justify-content: space-between; gap: 16px; padding: 20px 2px; background: none; border: 0; border-bottom: 1px solid #ECEAE5; border-radius: 0; cursor: pointer; font-family: inherit; font-size: 13px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: #1A1A1A; text-align: left; }
  .nur-info__row:hover { color: #C8A96E; }
  .nur-info__row svg { width: 16px; height: 16px; flex-shrink: 0; stroke: currentColor; fill: none; stroke-width: 1.6; }
  .nur-drawer { position: fixed; inset: 0 0 0 auto; margin: 0; width: min(480px, 100vw); max-width: 100vw; height: 100dvh; max-height: 100dvh; padding: 0; border: 0; border-radius: 0; background: #FFFFFF; color: #1A1A1A; font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; box-shadow: -12px 0 40px rgba(0,0,0,0.12); overflow: hidden; }
  .nur-drawer[open] { display: flex; flex-direction: column; animation: nur-drawer-in 0.32s ease; }
  .nur-drawer::backdrop { background: rgba(26,26,26,0.45); }
  @keyframes nur-drawer-in { from { transform: translateX(100%); } to { transform: translateX(0); } }
  .nur-drawer__head { display: flex; align-items: center; justify-content: space-between; padding: 26px 32px; border-bottom: 1px solid #ECEAE5; flex-shrink: 0; }
  .nur-drawer__title { margin: 0; font-size: 15px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: #1A1A1A; }
  .nur-drawer__close { display: flex; align-items: center; justify-content: center; width: 36px; height: 36px; padding: 0; background: none; border: 0; cursor: pointer; color: #1A1A1A; }
  .nur-drawer__close:focus:not(:focus-visible) { outline: none; }
  .nur-drawer__close svg { width: 18px; height: 18px; stroke: currentColor; stroke-width: 1.6; fill: none; }
  .nur-drawer__body { flex: 1; padding: 28px 32px 40px; overflow-y: auto; -webkit-overflow-scrolling: touch; }
  .nur-drawer__body h4 { margin: 0 0 6px; font-size: 14px; font-weight: 700; color: #1A1A1A; }
  .nur-drawer__body p, .nur-drawer__body li { font-size: 14px; line-height: 1.7; color: #4A4A4A; }
  .nur-drawer__body p { margin: 0 0 24px; }
  .nur-drawer__body ul { margin: 0 0 24px; padding-left: 18px; }
  .nur-drawer__body a { color: #1A1A1A; text-decoration: underline; text-underline-offset: 3px; }
  .nur-spec { margin: 0 0 22px; }
  .nur-spec__label { display: block; font-size: 14px; font-weight: 700; color: #1A1A1A; margin-bottom: 4px; }
  .nur-spec__value { font-size: 14px; line-height: 1.7; color: #4A4A4A; }
  .nur-drawer__body .nur-waves { list-style: none; margin: 4px 0 0; padding: 0; }
  .nur-waves li { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px solid #F2EFE8; }
  .nur-waves li span:last-child { font-family: 'Courier New', Courier, monospace; font-weight: 600; color: #1A1A1A; white-space: nowrap; }
  .nur-step { display: grid; grid-template-columns: 34px 1fr; gap: 0 10px; margin-bottom: 22px; }
  .nur-step__num { font-size: 13px; font-weight: 600; color: #C8A96E; letter-spacing: 1px; padding-top: 1px; }
  .nur-step__title { display: block; font-size: 14px; font-weight: 700; color: #1A1A1A; margin-bottom: 4px; }
  .nur-step__text { display: block; font-size: 14px; line-height: 1.7; color: #4A4A4A; }
  .nur-drawer__note { padding-top: 18px; border-top: 1px solid #ECEAE5; font-size: 13px !important; }
  @media (max-width: 749px) {
    .nur-drawer__head { padding: 20px 20px; }
    .nur-drawer__body { padding: 22px 20px 36px; }
  }
</style>

<div class="nur-info">
  <button type="button" class="nur-info__row" data-nur-drawer="nur-drawer-specs">
    <span>{% if nur_fr %}Fiche technique{% else %}Tech specs{% endif %}</span>
    <svg viewBox="0 0 24 24" aria-hidden="true"><polyline points="9 6 15 12 9 18"></polyline></svg>
  </button>
  <button type="button" class="nur-info__row" data-nur-drawer="nur-drawer-deposit">
    <span>{% if nur_fr %}Réserver avec acompte{% else %}Reserving with a deposit{% endif %}</span>
    <svg viewBox="0 0 24 24" aria-hidden="true"><polyline points="9 6 15 12 9 18"></polyline></svg>
  </button>
  <button type="button" class="nur-info__row" data-nur-drawer="nur-drawer-faq">
    <span>FAQ</span>
    <svg viewBox="0 0 24 24" aria-hidden="true"><polyline points="9 6 15 12 9 18"></polyline></svg>
  </button>
</div>

<dialog class="nur-drawer" id="nur-drawer-specs" aria-labelledby="nur-drawer-specs-title">
  <div class="nur-drawer__head">
    <h3 class="nur-drawer__title" id="nur-drawer-specs-title">{% if nur_fr %}Fiche technique{% else %}Tech specs{% endif %}</h3>
    <button type="button" class="nur-drawer__close" data-nur-close aria-label="{% if nur_fr %}Fermer{% else %}Close{% endif %}"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
  </div>
  <div class="nur-drawer__body">
    <div class="nur-spec">
      <span class="nur-spec__label">{% if nur_fr %}Zones traitées{% else %}Treatment areas{% endif %}</span>
      <span class="nur-spec__value">{% if nur_fr %}Masque visage + panneau cou et décolleté{% else %}Face mask + neck and décolleté panel{% endif %}</span>
    </div>
    <div class="nur-spec">
      <span class="nur-spec__label">{% if nur_fr %}Longueurs d’onde{% else %}Wavelengths{% endif %}</span>
      <ul class="nur-waves">
        <li><span>{% if nur_fr %}Rouge{% else %}Red{% endif %}</span><span>633 nm</span></li>
        <li><span>{% if nur_fr %}Bleu{% else %}Blue{% endif %}</span><span>440–450 nm</span></li>
        <li><span>{% if nur_fr %}Jaune{% else %}Yellow{% endif %}</span><span>590 nm</span></li>
        <li><span>{% if nur_fr %}Vert{% else %}Green{% endif %}</span><span>540–550 nm</span></li>
        <li><span>Cyan</span><span>490 nm</span></li>
        <li><span>{% if nur_fr %}Blanc{% else %}White{% endif %}</span><span>440–630 nm</span></li>
        <li><span>Magenta</span><span>{% if nur_fr %}Rouge + Bleu{% else %}Red + Blue{% endif %}</span></li>
      </ul>
    </div>
    <div class="nur-spec">
      <span class="nur-spec__label">Irradiance</span>
      <span class="nur-spec__value">30 mW/cm²</span>
    </div>
    <div class="nur-spec">
      <span class="nur-spec__label">{% if nur_fr %}Coach IA{% else %}AI skincoach{% endif %}</span>
      <span class="nur-spec__value">{% if nur_fr %}Application NŪR Skincoach, accessible avec votre carte Gold digitale (QR code){% else %}NŪR Skincoach app, accessed with your digital Gold Card (QR code){% endif %}</span>
    </div>
    <div class="nur-spec">
      <span class="nur-spec__label">{% if nur_fr %}Contenu de la boîte{% else %}What’s in the box{% endif %}</span>
      <ul>
        <li>{% if nur_fr %}Masque LED visage NŪR Protocol{% else %}NŪR Protocol LED face mask{% endif %}</li>
        <li>{% if nur_fr %}Panneau LED cou et décolleté NŪR Protocol{% else %}NŪR Protocol LED neck and décolleté panel{% endif %}</li>
        <li>{% if nur_fr %}Télécommande{% else %}Handheld controller{% endif %}</li>
        <li>{% if nur_fr %}2 sangles réglables{% else %}2 adjustable straps{% endif %}</li>
        <li>{% if nur_fr %}2 protections oculaires en silicone{% else %}2 silicone eye protectors{% endif %}</li>
        <li>{% if nur_fr %}Câble de charge USB-C{% else %}USB-C charging cable{% endif %}</li>
        <li>{% if nur_fr %}Manuel d’utilisation{% else %}User manual{% endif %}</li>
        <li>{% if nur_fr %}Carte d’accès NŪR Skincoach{% else %}NŪR Skincoach access card{% endif %}</li>
      </ul>
    </div>
    <div class="nur-spec">
      <span class="nur-spec__label">{% if nur_fr %}Garantie{% else %}Warranty{% endif %}</span>
      <span class="nur-spec__value">{% if nur_fr %}1 an{% else %}1 year{% endif %}</span>
    </div>
  </div>
</dialog>

<dialog class="nur-drawer" id="nur-drawer-deposit" aria-labelledby="nur-drawer-deposit-title">
  <div class="nur-drawer__head">
    <h3 class="nur-drawer__title" id="nur-drawer-deposit-title">{% if nur_fr %}Réserver avec acompte{% else %}Reserving with a deposit{% endif %}</h3>
    <button type="button" class="nur-drawer__close" data-nur-close aria-label="{% if nur_fr %}Fermer{% else %}Close{% endif %}"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
  </div>
  <div class="nur-drawer__body">
    <div class="nur-step">
      <span class="nur-step__num">01</span>
      <span>
        <span class="nur-step__title">{% if nur_fr %}Aujourd’hui{% else %}Today{% endif %}</span>
        <span class="nur-step__text">{% if nur_fr %}Vous réglez un acompte de 20&nbsp;% ({{ nur_deposit | money }}). Votre carte est enregistrée de façon sécurisée par Shopify pour le solde.{% else %}You pay a 20% deposit ({{ nur_deposit | money }}). Your card is securely saved by Shopify for the balance.{% endif %}</span>
      </span>
    </div>
    <div class="nur-step">
      <span class="nur-step__num">02</span>
      <span>
        <span class="nur-step__title">{% if nur_fr %}Le 4 décembre{% else %}December 4{% endif %}</span>
        <span class="nur-step__text">{% if nur_fr %}Le solde ({{ nur_balance | money }}, ou {{ nur_balance_code | money }} avec un code promo) est prélevé automatiquement, juste avant l’expédition.{% else %}The balance ({{ nur_balance | money }}, or {{ nur_balance_code | money }} with a promo code) is charged automatically, just before shipping.{% endif %}</span>
      </span>
    </div>
    {%- if nur_early -%}
    <div class="nur-step">
      <span class="nur-step__num">03</span>
      <span>
        <span class="nur-step__title">{% if nur_fr %}Avant Noël{% else %}Before Christmas{% endif %}</span>
        <span class="nur-step__text">{% if nur_fr %}Votre NŪR Protocol vous est livré. Livraison prévue avant Noël pour toute réservation jusqu’au 25 novembre.{% else %}Your NŪR Protocol is delivered. Delivery planned before Christmas for reservations made by November 25.{% endif %}</span>
      </span>
    </div>
    {%- endif -%}
    <p class="nur-drawer__note">{% if nur_fr %}Vous préférez tout régler maintenant&nbsp;? Choisissez «&nbsp;Paiement intégral&nbsp;» dans les options de paiement.{% else %}Prefer to pay in full now? Choose “Full Payment” in the payment options.{% endif %}</p>
  </div>
</dialog>

<dialog class="nur-drawer" id="nur-drawer-faq" aria-labelledby="nur-drawer-faq-title">
  <div class="nur-drawer__head">
    <h3 class="nur-drawer__title" id="nur-drawer-faq-title">FAQ</h3>
    <button type="button" class="nur-drawer__close" data-nur-close aria-label="{% if nur_fr %}Fermer{% else %}Close{% endif %}"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
  </div>
  <div class="nur-drawer__body">
    {%- if nur_early -%}
    <h4>{% if nur_fr %}Quand vais-je recevoir mon masque&nbsp;?{% else %}When will I receive my mask?{% endif %}</h4>
    <p>{% if nur_fr %}Les réservations faites jusqu’au 25 novembre (23&nbsp;h&nbsp;59, heure de Paris) partent avec notre première expédition de décembre, avec une livraison prévue avant Noël. Vous recevez un numéro de suivi dès l’expédition.{% else %}Reservations made by November 25 (11:59 PM Paris time) are part of our first December shipment, with delivery planned before Christmas. You receive a tracking number as soon as your order ships.{% endif %}</p>
    {%- endif -%}
    <h4>{% if nur_fr %}Comment accéder à NŪR Skincoach&nbsp;?{% else %}How do I access NŪR Skincoach?{% endif %}</h4>
    <p>{% if nur_fr %}Votre carte Gold digitale contient un QR code qui vous donne accès à l’application NŪR Skincoach. Une carte d’accès est aussi incluse dans votre coffret.{% else %}Your digital Gold Card includes a QR code that gives you access to the NŪR Skincoach app. An access card is also included in your box.{% endif %}</p>
    <h4>{% if nur_fr %}Puis-je payer en plusieurs fois&nbsp;?{% else %}Can I pay in instalments?{% endif %}</h4>
    <p>{% if nur_fr %}Oui. Vous pouvez réserver avec un acompte de 20&nbsp;% et régler le solde le 4 décembre, ou payer en 3 fois avec Klarna au moment du paiement.{% else %}Yes. You can reserve with a 20% deposit and pay the balance on December 4, or pay in 3 instalments with Klarna at checkout.{% endif %}</p>
    <h4>{% if nur_fr %}Comment fonctionne un code promo&nbsp;?{% else %}How do promo codes work?{% endif %}</h4>
    <p>{% if nur_fr %}Saisissez votre code au moment du paiement&nbsp;: il retire 10&nbsp;% du prix complet de votre coffret. Si vous réservez avec acompte, la réduction est déduite du solde.{% else %}Enter your code at checkout: it takes 10% off the full price of your set. If you reserve with a deposit, the discount comes off the balance.{% endif %}</p>
    <h4>{% if nur_fr %}Où livrez-vous&nbsp;?{% else %}Where do you ship?{% endif %}</h4>
    <p>{% if nur_fr %}Nous livrons dans le monde entier. Les frais de livraison pour votre pays s’affichent au moment du paiement.{% else %}We ship worldwide. Shipping costs for your country are shown at checkout.{% endif %}</p>
    <h4>{% if nur_fr %}Quelle est la garantie&nbsp;?{% else %}What warranty do I get?{% endif %}</h4>
    <p>{% if nur_fr %}Votre NŪR Protocol est garanti 1 an.{% else %}Your NŪR Protocol comes with a 1-year warranty.{% endif %}</p>
    <h4>{% if nur_fr %}Une autre question&nbsp;?{% else %}Another question?{% endif %}</h4>
    <p>{% if nur_fr %}Écrivez-nous depuis notre <a href="{{ nur_root }}/pages/contact">page contact</a>&nbsp;: nous vous répondons personnellement.{% else %}Write to us from our <a href="{{ nur_root }}/pages/contact">contact page</a>: we reply personally.{% endif %}</p>
  </div>
</dialog>

<script>
  (function () {
    document.querySelectorAll('[data-nur-drawer]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var d = document.getElementById(btn.getAttribute('data-nur-drawer'));
        if (d && typeof d.showModal === 'function') { d.showModal(); }
      });
    });
    document.querySelectorAll('.nur-drawer').forEach(function (d) {
      d.addEventListener('click', function (e) {
        if (e.target === d || e.target.closest('[data-nur-close]')) { d.close(); }
      });
    });
  })();
</script>
